-- 用最大可用分区防止有人错误回刷造成线上数据有问题
set last_partition_${grass_region_without_quote} = (
select
    max(time_str)
from(
    SELECT
        concat(regional_date,'_',if(regional_hour<10,concat('0',regional_hour),regional_hour)) as  time_str
    FROM srdi_mart.ods_sr_data_warehouse_vsku_supply_info_hf
    where grass_region in (${grass_region}) and regional_date >= ${regional_date} -- 一定程度缩小scan范围，这个ods表虽然只有一个月的留存
    group by regional_date,regional_hour
) a
);
--sql_divide_splitter--

CREATE TEMPORARY VIEW new_supply_info_${grass_region_without_quote} AS
select
    model_id
   ,cast(get_json_object(supply_info,'$.display_promo_result.item_promo_infos[0].model_promo_infos[0].main.price.supply_price') as bigint) / 100000 as supply_price
   ,grass_region
   ,regional_date
   ,regional_hour
from srdi_mart.ods_sr_data_warehouse_vsku_supply_info_hf
where grass_region in (${grass_region}) and regional_date = split(${last_partition_${grass_region_without_quote}},'_')[0]
and regional_hour = cast(split(${last_partition_${grass_region_without_quote}},'_')[1] as int)
;
--sql_divide_splitter--

